export type EventCallback<T = any> = (payload: T) => void;

export class EventBus {
  private subscribers: Map<string, EventCallback<any>[]> = new Map();

  publish<T = any>(event: string, payload: T): void {
    const subs = this.subscribers.get(event) || [];
    // Call subscribers synchronously
    for (const cb of subs) {
      try {
        cb(payload);
      } catch (err) {
        // Swallow to avoid breaking publisher
        // In a real system, we'd log this
      }
    }
  }

  subscribe<T = any>(event: string, callback: EventCallback<T>): void {
    const subs = this.subscribers.get(event) || [];
    subs.push(callback as EventCallback<any>);
    this.subscribers.set(event, subs);
  }
}

import { randomUUID } from 'crypto';

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private store: Map<string, User> = new Map();

  create(input: Omit<User, 'id'>): User {
    const id = randomUUID();
    const user: User = { id, ...input };
    this.store.set(id, user);
    return user;
  }

  getById(id: string): User | undefined {
    return this.store.get(id);
  }

  getAll(): User[] {
    return Array.from(this.store.values());
  }

  update(id: string, input: Partial<Omit<User, 'id'>>): User | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;
    const updated: User = { ...existing, ...input, id };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

import { randomUUID } from 'crypto';

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export class ProjectService {
  private store: Map<string, Project> = new Map();

  create(input: Omit<Project, 'id' | 'memberIds'> & { memberIds?: string[] }): Project {
    const id = randomUUID();
    const project: Project = { id, name: input.name, description: input.description, memberIds: input.memberIds || [] };
    this.store.set(id, project);
    return project;
  }

  getById(id: string): Project | undefined {
    return this.store.get(id);
  }

  getAll(): Project[] {
    return Array.from(this.store.values());
  }

  update(id: string, input: Partial<Omit<Project, 'id'>>): Project | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;
    const updated: Project = { ...existing, ...input, id, memberIds: input.memberIds ?? existing.memberIds };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }

  addMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;
    if (!project.memberIds.includes(userId)) {
      project.memberIds = [...project.memberIds, userId];
      this.store.set(projectId, project);
    }
    return project;
  }

  removeMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;
    project.memberIds = project.memberIds.filter((id) => id !== userId);
    this.store.set(projectId, project);
    return project;
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export class TaskService {
  private store: Map<string, Task> = new Map();

  constructor(private eventBus: EventBus) {}

  create(input: Omit<Task, 'id' | 'status' | 'assigneeId'> & { status?: TaskStatus; assigneeId?: string | null }): Task {
    const id = randomUUID();
    const task: Task = {
      id,
      title: input.title,
      description: input.description,
      projectId: input.projectId,
      status: input.status ?? 'todo',
      assigneeId: input.assigneeId ?? null,
    };
    this.store.set(id, task);
    return task;
  }

  getById(id: string): Task | undefined {
    return this.store.get(id);
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter((t) => t.projectId === projectId);
  }

  getAll(): Task[] {
    return Array.from(this.store.values());
  }

  update(id: string, input: Partial<Omit<Task, 'id'>>): Task | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;
    const merged: Task = { ...existing, ...input, id };
    // Enforce forward-only status transitions if status provided
    if (input.status && existing.status !== input.status) {
      if (!this.isForwardTransition(existing.status, input.status)) {
        throw new Error('Invalid status transition');
      }
    }
    this.store.set(id, merged);
    return merged;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }

  assign(id: string, assigneeId: string | null): Task | undefined {
    const task = this.store.get(id);
    if (!task) return undefined;
    task.assigneeId = assigneeId;
    this.store.set(id, task);
    if (assigneeId) {
      this.eventBus.publish('task.assigned', { taskId: id, taskTitle: task.title, assigneeId });
    }
    return task;
  }

  changeStatus(id: string, newStatus: TaskStatus): Task | undefined {
    const task = this.store.get(id);
    if (!task) return undefined;
    const oldStatus = task.status;
    if (oldStatus === newStatus) return task;
    if (!this.isForwardTransition(oldStatus, newStatus)) {
      throw new Error('Invalid status transition');
    }
    task.status = newStatus;
    this.store.set(id, task);
    this.eventBus.publish('task.statusChanged', {
      taskId: id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    });
    return task;
  }

  private isForwardTransition(oldStatus: TaskStatus, newStatus: TaskStatus): boolean {
    const order: TaskStatus[] = ['todo', 'in-progress', 'done'];
    return order.indexOf(newStatus) >= order.indexOf(oldStatus);
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export class CommentService {
  private store: Map<string, Comment> = new Map();

  constructor(private eventBus: EventBus, private getTaskTitle: (taskId: string) => string | undefined, private getUserName: (userId: string) => string | undefined) {}

  create(input: Omit<Comment, 'id' | 'createdAt'>): Comment {
    const id = randomUUID();
    const createdAt = new Date().toISOString();
    const comment: Comment = { id, ...input, createdAt };
    this.store.set(id, comment);

    // publish event on comment added
    const taskTitle = this.getTaskTitle(input.taskId) || 'Task';
    const authorName = this.getUserName(input.authorId) || 'Someone';
    this.eventBus.publish('comment.added', {
      commentId: id,
      taskId: input.taskId,
      taskTitle,
      authorId: input.authorId,
      authorName,
    });

    return comment;
  }

  getById(id: string): Comment | undefined {
    return this.store.get(id);
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter((c) => c.taskId === taskId);
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

export class NotificationService {
  private store: Map<string, Notification> = new Map();
  // Internal cache of task assignees maintained from events
  private taskAssignees: Map<string, string | null> = new Map();

  constructor(private eventBus: EventBus) {
    this.eventBus.subscribe('task.assigned', (payload: { taskId: string; taskTitle: string; assigneeId: string }) => {
      this.taskAssignees.set(payload.taskId, payload.assigneeId);
      const message = `Task '${payload.taskTitle}' assigned to you.`;
      this.createNotification(payload.assigneeId, message);
    });

    this.eventBus.subscribe(
      'task.statusChanged',
      (payload: { taskId: string; taskTitle: string; assigneeId: string | null; oldStatus: string; newStatus: string }) => {
        this.taskAssignees.set(payload.taskId, payload.assigneeId ?? null);
        if (payload.assigneeId) {
          const message = `Task '${payload.taskTitle}' status changed from ${payload.oldStatus} to ${payload.newStatus}.`;
          this.createNotification(payload.assigneeId, message);
        }
      }
    );

    this.eventBus.subscribe(
      'comment.added',
      (payload: { commentId: string; taskId: string; taskTitle: string; authorId: string; authorName: string }) => {
        const assigneeId = this.taskAssignees.get(payload.taskId);
        if (assigneeId) {
          const message = `New comment by ${payload.authorName} on task '${payload.taskTitle}'.`;
          this.createNotification(assigneeId, message);
        }
      }
    );
  }

  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.store.set(notification.id, notification);
    return notification;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter((n) => n.userId === userId);
  }

  markAsRead(id: string): Notification | undefined {
    const n = this.store.get(id);
    if (!n) return undefined;
    n.read = true;
    this.store.set(id, n);
    return n;
  }
}

import http, { IncomingMessage, ServerResponse } from 'http';
import { parse as parseUrl } from 'url';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService, TaskStatus } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';

export interface Services {
  userService: UserService;
  projectService: ProjectService;
  taskService: TaskService;
  commentService: CommentService;
  notificationService: NotificationService;
}

function sendJson(res: ServerResponse, status: number, data: any): void {
  const payload = JSON.stringify(data);
  res.statusCode = status;
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Content-Length', Buffer.byteLength(payload));
  res.end(payload);
}

function sendNoContent(res: ServerResponse): void {
  res.statusCode = 204;
  res.end();
}

async function readBody(req: IncomingMessage): Promise<any> {
  const chunks: Buffer[] = [];
  for await (const chunk of req) {
    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
  }
  if (chunks.length === 0) return undefined;
  const raw = Buffer.concat(chunks).toString('utf8');
  try {
    return JSON.parse(raw);
  } catch (e) {
    return undefined;
  }
}

export function createHttpServer(services: Services): http.Server {
  const server = http.createServer(async (req, res) => {
    const method = req.method || 'GET';
    const url = req.url || '/';
    const { pathname, query } = parseUrl(url, true);

    try {
      // Users
      if (method === 'GET' && pathname === '/users') {
        const users = services.userService.getAll();
        return sendJson(res, 200, users);
      }
      if (method === 'POST' && pathname === '/users') {
        const body = await readBody(req);
        if (!body || typeof body.name !== 'string' || typeof body.email !== 'string') {
          return sendJson(res, 400, { error: 'Invalid body' });
        }
        const user = services.userService.create({ name: body.name, email: body.email });
        return sendJson(res, 201, user);
      }
      if (pathname && /^\/users\/.+/.test(pathname)) {
        const id = pathname.split('/')[2];
        if (method === 'GET') {
          const user = services.userService.getById(id);
          if (!user) return sendJson(res, 404, { error: 'Not found' });
          return sendJson(res, 200, user);
        }
        if (method === 'PUT') {
          const body = await readBody(req);
          const updated = services.userService.update(id, body || {});
          if (!updated) return sendJson(res, 404, { error: 'Not found' });
          return sendJson(res, 200, updated);
        }
        if (method === 'DELETE') {
          const ok = services.userService.delete(id);
          if (!ok) return sendJson(res, 404, { error: 'Not found' });
          return sendNoContent(res);
        }
      }

      // Projects
      if (method === 'GET' && pathname === '/projects') {
        const projects = services.projectService.getAll();
        return sendJson(res, 200, projects);
      }
      if (method === 'POST' && pathname === '/projects') {
        const body = await readBody(req);
        if (!body || typeof body.name !== 'string' || typeof body.description !== 'string') {
          return sendJson(res, 400, { error: 'Invalid body' });
        }
        const project = services.projectService.create({ name: body.name, description: body.description, memberIds: body.memberIds });
        return sendJson(res, 201, project);
      }
      if (pathname && /^\/projects\/.+/.test(pathname)) {
        const parts = pathname.split('/');
        const id = parts[2];
        if (parts.length === 3) {
          if (method === 'GET') {
            const project = services.projectService.getById(id);
            if (!project) return sendJson(res, 404, { error: 'Not found' });
            return sendJson(res, 200, project);
          }
          if (method === 'PUT') {
            const body = await readBody(req);
            const updated = services.projectService.update(id, body || {});
            if (!updated) return sendJson(res, 404, { error: 'Not found' });
            return sendJson(res, 200, updated);
          }
          if (method === 'DELETE') {
            const ok = services.projectService.delete(id);
            if (!ok) return sendJson(res, 404, { error: 'Not found' });
            return sendNoContent(res);
          }
        }
        if (parts.length === 4 && parts[3] === 'members') {
          const body = await readBody(req);
          if (!body || typeof body.userId !== 'string') {
            return sendJson(res, 400, { error: 'Invalid body' });
          }
          if (method === 'POST') {
            const updated = services.projectService.addMember(id, body.userId);
            if (!updated) return sendJson(res, 404, { error: 'Not found' });
            return sendJson(res, 200, updated);
          }
          if (method === 'DELETE') {
            const updated = services.projectService.removeMember(id, body.userId);
            if (!updated) return sendJson(res, 404, { error: 'Not found' });
            return sendJson(res, 200, updated);
          }
        }
      }

      // Tasks
      if (method === 'GET' && pathname === '/tasks') {
        const projectId = (query && (query as any).projectId) as string | undefined;
        if (!projectId) return sendJson(res, 400, { error: 'projectId required' });
        const tasks = services.taskService.getByProject(projectId);
        return sendJson(res, 200, tasks);
      }
      if (method === 'POST' && pathname === '/tasks') {
        const body = await readBody(req);
        if (!body || typeof body.title !== 'string' || typeof body.description !== 'string' || typeof body.projectId !== 'string') {
          return sendJson(res, 400, { error: 'Invalid body' });
        }
        const task = services.taskService.create({ title: body.title, description: body.description, projectId: body.projectId, status: body.status, assigneeId: body.assigneeId });
        return sendJson(res, 201, task);
      }
      if (pathname && /^\/tasks\/.+/.test(pathname)) {
        const parts = pathname.split('/');
        const id = parts[2];
        if (parts.length === 3) {
          if (method === 'GET') {
            const task = services.taskService.getById(id);
            if (!task) return sendJson(res, 404, { error: 'Not found' });
            return sendJson(res, 200, task);
          }
          if (method === 'PUT') {
            const body = await readBody(req);
            try {
              const updated = services.taskService.update(id, body || {});
              if (!updated) return sendJson(res, 404, { error: 'Not found' });
              return sendJson(res, 200, updated);
            } catch (e: any) {
              return sendJson(res, 400, { error: e.message || 'Bad Request' });
            }
          }
          if (method === 'DELETE') {
            const ok = services.taskService.delete(id);
            if (!ok) return sendJson(res, 404, { error: 'Not found' });
            return sendNoContent(res);
          }
        }
        if (parts.length === 4 && parts[3] === 'status' && method === 'PUT') {
          const body = await readBody(req);
          const status = body?.status as TaskStatus | undefined;
          if (!status) return sendJson(res, 400, { error: 'status required' });
          try {
            const updated = services.taskService.changeStatus(id, status);
            if (!updated) return sendJson(res, 404, { error: 'Not found' });
            return sendJson(res, 200, updated);
          } catch (e: any) {
            return sendJson(res, 400, { error: e.message || 'Bad Request' });
          }
        }
        if (parts.length === 4 && parts[3] === 'assign' && method === 'PUT') {
          const body = await readBody(req);
          const assigneeId = (body ? body.assigneeId : undefined) as string | null | undefined;
          const updated = services.taskService.assign(id, assigneeId ?? null);
          if (!updated) return sendJson(res, 404, { error: 'Not found' });
          return sendJson(res, 200, updated);
        }
      }

      // Comments
      if (method === 'GET' && pathname === '/comments') {
        const taskId = (query && (query as any).taskId) as string | undefined;
        if (!taskId) return sendJson(res, 400, { error: 'taskId required' });
        const comments = services.commentService.getByTask(taskId);
        return sendJson(res, 200, comments);
      }
      if (method === 'POST' && pathname === '/comments') {
        const body = await readBody(req);
        if (!body || typeof body.taskId !== 'string' || typeof body.authorId !== 'string' || typeof body.body !== 'string') {
          return sendJson(res, 400, { error: 'Invalid body' });
        }
        const comment = services.commentService.create({ taskId: body.taskId, authorId: body.authorId, body: body.body });
        return sendJson(res, 201, comment);
      }
      if (pathname && /^\/comments\/.+/.test(pathname)) {
        const id = pathname.split('/')[2];
        if (method === 'GET') {
          const c = services.commentService.getById(id);
          if (!c) return sendJson(res, 404, { error: 'Not found' });
          return sendJson(res, 200, c);
        }
        if (method === 'DELETE') {
          const ok = services.commentService.delete(id);
          if (!ok) return sendJson(res, 404, { error: 'Not found' });
          return sendNoContent(res);
        }
      }

      // Notifications
      if (method === 'GET' && pathname === '/notifications') {
        const userId = (query && (query as any).userId) as string | undefined;
        if (!userId) return sendJson(res, 400, { error: 'userId required' });
        const notifs = services.notificationService.getByUser(userId);
        return sendJson(res, 200, notifs);
      }
      if (pathname && /^\/notifications\/.+\/read$/.test(pathname) && method === 'PUT') {
        const id = pathname.split('/')[2];
        const updated = services.notificationService.markAsRead(id);
        if (!updated) return sendJson(res, 404, { error: 'Not found' });
        return sendJson(res, 200, updated);
      }

      // Fallback
      sendJson(res, 404, { error: 'Route not found' });
    } catch (err: any) {
      sendJson(res, 500, { error: 'Internal Server Error', details: err?.message });
    }
  });

  return server;
}

import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';
import { createHttpServer } from './router';

const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;

async function start() {
  const eventBus = new EventBus();

  const userService = new UserService();
  const projectService = new ProjectService();
  const taskService = new TaskService(eventBus);

  // For comment service, we need functions to resolve task title and user name without direct service references.
  const getTaskTitle = (taskId: string): string | undefined => {
    const task = taskService.getById(taskId);
    return task?.title;
  };
  const getUserName = (userId: string): string | undefined => {
    const user = userService.getById(userId);
    return user?.name;
  };

  const commentService = new CommentService(eventBus, getTaskTitle, getUserName);
  const notificationService = new NotificationService(eventBus);

  const server = createHttpServer({ userService, projectService, taskService, commentService, notificationService });

  server.listen(PORT, () => {
    console.log(`Task Management API listening on http://localhost:${PORT}`);
  });
}

start();

import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService, TaskStatus } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';
import { createHttpServer } from './router';
import http from 'http';

const PORT = 3001;

function request(method: string, path: string, body?: any): Promise<any> {
  return new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : undefined;
    const req = http.request(
      {
        hostname: 'localhost',
        port: PORT,
        path,
        method,
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': data ? Buffer.byteLength(data) : 0,
        },
      },
      (res) => {
        const chunks: Buffer[] = [];
        res.on('data', (chunk) => chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)));
        res.on('end', () => {
          const text = Buffer.concat(chunks).toString('utf8');
          try {
            const json = text ? JSON.parse(text) : undefined;
            resolve({ status: res.statusCode, body: json });
          } catch (e) {
            resolve({ status: res.statusCode, body: text });
          }
        });
      }
    );
    req.on('error', reject);
    if (data) req.write(data);
    req.end();
  });
}

async function runDemo() {
  // Start in-memory server
  const eventBus = new EventBus();
  const userService = new UserService();
  const projectService = new ProjectService();
  const taskService = new TaskService(eventBus);
  const getTaskTitle = (taskId: string) => taskService.getById(taskId)?.title;
  const getUserName = (userId: string) => userService.getById(userId)?.name;
  const commentService = new CommentService(eventBus, getTaskTitle, getUserName);
  const notificationService = new NotificationService(eventBus);
  const server = createHttpServer({ userService, projectService, taskService, commentService, notificationService });
  await new Promise<void>((resolve) => server.listen(PORT, resolve));
  console.log(`Demo server on http://localhost:${PORT}`);

  // Create users
  const u1 = (await request('POST', '/users', { name: 'Alice', email: 'alice@example.com' })).body;
  const u2 = (await request('POST', '/users', { name: 'Bob', email: 'bob@example.com' })).body;
  console.log('Users created:', u1, u2);

  // Create project
  const project = (await request('POST', '/projects', { name: 'Project X', description: 'Top secret' })).body;
  console.log('Project created:', project);

  // Add members
  await request('POST', `/projects/${project.id}/members`, { userId: u1.id });
  await request('POST', `/projects/${project.id}/members`, { userId: u2.id });
  console.log('Members added');

  // Create tasks
  const t1 = (await request('POST', '/tasks', { title: 'Design UI', description: 'Create mockups', projectId: project.id })).body;
  const t2 = (await request('POST', '/tasks', { title: 'Implement API', description: 'Build endpoints', projectId: project.id })).body;
  console.log('Tasks created:', t1, t2);

  // Assign tasks
  await request('PUT', `/tasks/${t1.id}/assign`, { assigneeId: u1.id });
  await request('PUT', `/tasks/${t2.id}/assign`, { assigneeId: u2.id });
  console.log('Tasks assigned');

  // Change status
  await request('PUT', `/tasks/${t1.id}/status`, { status: 'in-progress' as TaskStatus });
  await request('PUT', `/tasks/${t1.id}/status`, { status: 'done' as TaskStatus });
  console.log('Task status changed');

  // Add comments
  await request('POST', '/comments', { taskId: t1.id, authorId: u2.id, body: 'Looks great!' });
  await request('POST', '/comments', { taskId: t2.id, authorId: u1.id, body: 'API endpoints ready?' });
  console.log('Comments added');

  // Check notifications
  const n1 = await request('GET', `/notifications?userId=${u1.id}`);
  const n2 = await request('GET', `/notifications?userId=${u2.id}`);
  console.log('Notifications for Alice:', n1.body);
  console.log('Notifications for Bob:', n2.body);

  // Mark first notification as read for Alice if exists
  if (n1.body && n1.body.length > 0) {
    const notifId = n1.body[0].id;
    await request('PUT', `/notifications/${notifId}/read`);
    const n1b = await request('GET', `/notifications?userId=${u1.id}`);
    console.log('Notifications for Alice after markAsRead:', n1b.body);
  }

  server.close();
}

runDemo().catch((err) => {
  console.error('Demo error:', err);
  process.exit(1);
});
